VALUES ('homepage:home', 'homepage', 'home', 'published', 0, '{"loader":{"word":"BCE., LTD.","titleLines":["Construction company","Infrastructure & building"],"locationLines":["Battambang","Cambodia"],"statusLines":["Loading","0%"]},"hero":{"video":"/video/hero_highlight.mp4","poster":"/Image/bce/hero_batching_plant.webp","image":"/assets/6ae3a.webp","imageAlt":"","titleLines":["Building on Strength.","Delivering with Trust."],"newsKicker":"Company profile","newsTitle":"Download the BCE Corporate Profile 2026","newsHref":"/assets/BCE_Corporate_Profile_2026_web.pdf","newsDownload":"BCE_Corporate_Profile_2026_web.pdf","newsImage":"/Image/bce/core_services.webp","newsAlt":"BCE Company Profile"},"about":{"image":"/assets/6ae3a.webp","imageAlt":"BCE architectural detail","intro":"BCE is a Battambang-based engineering and construction company, building across Cambodia since 1995 with modern equipment and a skilled team.","ctaLabel":"See more about us","ctaHref":"/?about","titleSegments":[{"text":"We supply ready-mix concrete","label":"Ready-Mix Concrete","icon":"plants","href":"/?business=ready-mix-concrete"},{"text":"foundation piling","label":"Foundation Piling","icon":"piling","href":"/?business=piling"},{"text":"civil construction","label":"Civil Construction","icon":"projects","href":"/?business=construction"},{"text":"slab works","label":"Concrete Slab Works","icon":"pump","href":"/?business=concrete-slab-works"},{"text":"and equipment rental","label":"Equipment Rental","icon":"mixer","href":"/?business=equipment-rental"}],"titleClosing":"across Cambodia."},"expertise":{"kicker":"Core business","lead":"Concrete supply, piling, construction, slab works and equipment rental under one roof.","scrollLabel":"Scroll to explore","titleLines":["Our core","business offering"]},"glance":{"title":"BCE at a glance 2025–2026","stats":[{"value":30,"suffix":"+","label":"Years of experience","note":"Established 1995","icon":"years"},{"value":128,"suffix":"","label":"Projects Comple