INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('quality:home', 'quality', 'home', 'published', 0, '{"cover":{"label":"Quality, capability & HSE","title":"Tested at every stage, built safely","image":"/Image/bce/photos/road-crew.webp","imageAlt":"BCE site crew in protective equipment placing and finishing concrete"},"intro":{"label":"Our approach","text":"Behind every BCE project is the capability to test, design and deliver concrete in-house: a quality process on every pour, our own laboratory, approved mix designs, certified materials, a fleet we own and maintain, and the engineers who bring it together."},"laboratory":{"title":"Laboratory & quality assurance","copy":"Strict quality control at every stage, with slump, strength and material testing at the plant and on site. Our own laboratory checks the materials that go into our concrete, the concrete as it leaves the plant and the strength it reaches once cured.","listLabel":"Our quality process","steps":[{"title":"Material check","text":"Every material checked before production."},{"title":"Batching","text":"Weighed and mixed to the approved design."},{"title":"Slump test","text":"Tested on delivery, before placing."},{"title":"Strength test","text":"Samples cured and tested in our lab."},{"title":"Verification","text":"Results checked and recorded."}],"tests":[{"label":"Slump testing","value":"Every delivery"},{"label":"Compressive strength","value":"7- and 28-day cubes"},{"label":"Aggregate grading","value":"Sieve analysis"},{"label":"Silt and moisture content","value":"Fine and coarse aggregate"},{"label":"Trial mixes","value":"For every new design"}],"image":"/Image/bce/cert_mix_design.webp","imageAlt":"Concrete test specimens side by side"},"materials":{"title":"Raw material certificates","copy":"Every material is certified at source and checked again before production, with certificates on file for each batch.","listLabel":"Certified materials","items":[{"name":"Cement","certificate":"Mill test certificate"},{"name":"Sand","certificate":"Grading and silt tests"},{"name":"Coarse aggregate","certificate":"Grading and crushing value"},{"name":"Admixtures","certificate":"Compliance certificate"},{"name":"Water","certificate":"Water quality tests"},{"name":"Steel","certificate":"Mill certificates"}],"image":"/Image/bce/project_page_14.webp","imageAlt":"Concrete specimens and raw materials"},"calibration":{"title":"Calibration certificates","copy":"The scales, meters and testing machines behind every result are calibrated on schedule, with certificates on file.","listLabel":"Calibrated equipment","items":[{"equipment":"Batching plant weigh scales","scope":"Cement, aggregate, water and admixture scales"},{"equipment":"Compression testing machine","scope":"Load calibration for cube and cylinder testing"},{"equipment":"Admixture dispensers","scope":"Dosing accuracy"},{"equipment":"Water meters","scope":"Flow accuracy at the batching plants"},{"equipment":"Laboratory equipment","scope":"Balances, slump cones and cube moulds"}]},"hse":{"label":"HSE commitment","heading":"HSE commitment: protecting people, working safely, respecting the environment","items":[{"lines":["Protecting","people"],"text":"We protect our people, our partners and the communities around every project we undertake.","image":"/Image/bce/hse_safety.webp","imageAlt":"BCE safety standards and protective equipment on site"},{"lines":["Working","safely"],"text":"Safe operations and a well-maintained fleet, run by a skilled and experienced team.","image":"/Image/bce/core_services.webp","imageAlt":"A site worker in an orange hard hat supervising pour"},{"lines":["Respecting","the environment"],"text":"We build today while protecting resources for future generations, through environmental responsibility and resource efficiency.","image":"/Image/bce/project_page_16.webp","imageAlt":"Environmental protection and clean site practices"},{"lines":["Delivering","quality"],"text":"Built to last. From certified batching to precision placement, laboratory quality control ensures every structure remains strong, durable and enduring.","image":"/Image/bce/cert_mix_design.webp","imageAlt":"A calibrated pressure gauge and quality testing"},{"lines":["Building","trust"],"text":"Stronger together. We grow alongside our clients, partners and suppliers through long-term relationships built on trust, respect and mutual success.","image":"/Image/bce/project_page_17.webp","imageAlt":"Construction engineering team collaborating on site"}]},"engineering":{"kicker":"People behind every project","title":"Engineering capability","image":"/Image/bce/stats_fleet.webp","imageAlt":"An engineer inspecting reinforcement on site","copy":["Our engineers plan, design and supervise every project, from mix design and piling programmes to site supervision and handover records."],"rows":[{"label":"Engineers","value":"15"},{"label":"Team","value":"71"},{"label":"Building since","value":"1995"},{"label":"Coverage","value":"13 provinces + Phnom Penh"}]},"fleet":{"kicker":"Our own fleet","title":"Equipment & fleet","image":"/Image/bce/about-zoom-boom-pumps.webp","imageAlt":"BCE pump trucks and mixer trucks placing concrete on site","copy":["Our plants and fleet are owned, operated and maintained by our own team, so capacity is planned around your programme rather than a supplier''s."],"rows":[{"label":"Batching plants","value":"04  /  70 m³/hr each"},{"label":"Mixer trucks","value":"41"},{"label":"Pump trucks","value":"08"},{"label":"Wheel loaders","value":"07"},{"label":"Piling rigs","value":"07"},{"label":"Crane trucks","value":"06"},{"label":"Tower cranes","value":"08"},{"label":"Lifts","value":"05"}],"ctaLabel":"Hire our equipment","ctaHref":"/?quote&service=equipment-rental"},"documents":{"label":"Quality documents","title":"Mix designs & certification","text":"The mix designs behind every grade, and the licences, certificates and company profile that procurement and tender teams ask for.","items":[{"title":"Company profile","subtitle":"BCE Corporate Profile 2026","status":"","date":"2026","size":"8.4 MB","file":"/assets/BCE_Corporate_Profile_2026_web.pdf"},{"title":"Mix design documents","subtitle":"Supplied with every mix design","status":"On request","date":"","size":"","file":""},{"title":"Business licence & registration","subtitle":"Ministry of Commerce","status":"On request","date":"","size":"","file":""},{"title":"Construction licence","subtitle":"Ministry of Land Management, Urban Planning and Construction","status":"On request","date":"","size":"","file":""},{"title":"Tax registration (VAT) certificate","subtitle":"General Department of Taxation","status":"On request","date":"","size":"","file":""}],"gradesText":"From blinding and mass fill to bridges and heavy structures, every grade is designed, trial-mixed and tested in our own laboratory before it reaches site.","grades":[{"grade":"C15","strength":"15 MPa","use":"Blinding and mass fill"},{"grade":"C20","strength":"20 MPa","use":"Ground slabs and paths"},{"grade":"C25","strength":"25 MPa","use":"Floor slabs and footings"},{"grade":"C30","strength":"30 MPa","use":"Columns, beams and suspended slabs"},{"grade":"C35","strength":"35 MPa","use":"Foundations and piles"},{"grade":"C40","strength":"40 MPa","use":"Bridges and heavy structures"}],"note":"Characteristic cube strength at 28 days. Other grades and special mixes designed on request.","ctaLabel":"Request documents","ctaHref":"#contact"},"title":"Quality & HSE","slug":"home"}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('about:home', 'about', 'home', 'published', 0, '{"cover":{"label":"Who we are","title":"About BCE","image":"/Image/bce/about-hero-banner.webp","imageAlt":"Aerial view of a BCE batching plant and aggregate yard"},"intro":{"text":"Battambang Construction and Engineering, Co., Ltd. (BCE) is a Battambang-based construction, concrete, piling and engineering company, supplying ready-mix concrete, reinforced concrete piling and civil construction to projects across Cambodia with its own plants, fleet and a team of 71.","primaryLabel":"Download Company Profile (PDF)","primaryHref":"/assets/BCE_Corporate_Profile_2026_web.pdf","secondaryLabel":"View all resources","secondaryHref":"/?resources"},"message":{"quote":"For more than thirty years we have built on four pillars: quality, safety, reliability and partnership. They guide every pour, every pile and every project.","attribution":"Chairwoman, BCE., Ltd."},"story":{"title":"Our story","text":"Founded in Battambang in 1995, BCE has grown into an integrated operation, delivering concrete, piling, construction, slab works and equipment rental with its own plants and fleet.","milestones":[{"year":"1995","text":"BCE is established in Battambang as an engineering and construction company."},{"year":"2025","text":"128 projects completed and 1,564 clients served in a single year."},{"year":"2026","text":"Operating across 13 provinces and Phnom Penh with 4 batching plants, 41 mixer trucks and 8 pump trucks."}]},"vision":{"sectionLabel":"Vision & mission","label":"Our vision","statement":"To be Cambodia’s most trusted partner for concrete, piling and construction."},"mission":{"label":"Our mission","statement":"To deliver quality-controlled concrete, foundations and construction on time and on spec, with our own plants, fleet and people."},"values":{"sectionLabel":"Core values","items":[{"title":"Quality","text":"Built to last. From material selection and production to construction and delivery, laboratory quality control keeps every structure strong, durable and lasting.","image":"/Image/bce/value-quality.webp","imageAlt":"Concrete frame and formwork rising beside a tower crane"},{"title":"Safety","text":"Our top priority. We protect our people, our partners and the communities we serve, from the batching plant to the project site.","image":"/Image/bce/value-safety.webp","imageAlt":"Crew working at height on scaffolding in high-visibility vests"},{"title":"Reliability","text":"On time, every time. Our own batching plants, mixer trucks and pump trucks give us the capacity to keep projects on schedule and on spec.","image":"/Image/bce/value-reliability.webp","imageAlt":"Tower crane and formwork keeping the construction programme on schedule"},{"title":"Partnership","text":"Stronger together. We grow alongside our clients, partners and suppliers through long-term relationships built on trust, respect and mutual success.","image":"/Image/bce/value-partnership.webp","imageAlt":"Two steel fixers working together on reinforcement"}]},"zoom":{"statements":["Engineering and construction, from Battambang across Cambodia since 1995","Concrete, piling, construction and fleet, all under one roof"]},"explore":{"label":"Explore more","tiles":[{"label":"What we do","title":"Our businesses","href":"/?businesses","image":"/Image/bce/about-business-banner.webp","imageAlt":"BCE site team reviewing a reinforced concrete slab"},{"label":"Tested at every stage","title":"Quality & HSE","href":"/?quality","image":"/Image/bce/about-hse-banner.webp","imageAlt":"Concrete cylinder under compression testing in the BCE laboratory"}]},"title":"About BCE","slug":"home"}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('projects:kampong-thom-bridge-foundations', 'projects', 'kampong-thom-bridge-foundations', 'published', 0, '{"slug":"kampong-thom-bridge-foundations","sample":true,"name":"Bridge Foundation Piling","owner":"Provincial public works authority","location":"Stueng Saen, Kampong Thom","period":"Feb 2024 – Sep 2024","category":"Piling","summary":"Reinforced concrete piles for a two-span river bridge on a provincial road, installed and tested by our own rigs and crews.","scope":["Supply of reinforced concrete piles","Pile installation at abutments and pier","Pile cap concrete from our batching plant","Load testing and as-built records"],"gallery":[{"image":"/Image/bce/project_page_28.webp","caption":"Hydraulic piling rig positioned at the foundation site"},{"image":"/Image/bce/project_page_29.webp","caption":"Deep foundation reinforcement and boring"},{"image":"/Image/bce/project_page_30.webp","caption":"Reinforced pile installation across the foundation grid"},{"image":"/Image/bce/project_page_31.webp","caption":"Completed foundation pile caps"}],"highlights":[{"value":"64","label":"Piles installed","note":"Abutments and pier"},{"value":"18","unit":"m","label":"Pile length","note":"Average per pile"},{"value":"420","unit":"m³","label":"Concrete supplied","note":"Pile caps and deck"},{"value":"7","unit":"mo","label":"Project period","note":"Feb – Sep 2024"}],"equipment":[{"name":"Piling rigs","count":2},{"name":"Mixer trucks","count":4},{"name":"Mobile crane","count":1},{"name":"Pump truck","count":1}],"technical":[{"label":"Pile type","value":"Precast RC square pile, 350 × 350 mm"},{"label":"Concrete grade","value":"C35 piles, C30 pile caps"},{"label":"Testing","value":"Static load test; cube strength at 7 and 28 days"}],"outcome":"Foundations were handed over ahead of the rainy season, so deck works could begin without delay."}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
