INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('projects:poipet-logistics-warehouse', 'projects', 'poipet-logistics-warehouse', 'published', 1, '{"slug":"poipet-logistics-warehouse","sample":true,"name":"Logistics Warehouse Floor Slab","owner":"Private logistics developer","location":"Poipet, Banteay Meanchey","period":"Jun 2024 – Dec 2024","category":"Concrete Slab Works","summary":"A heavy-duty ground-bearing slab for a cross-border logistics warehouse, poured in planned bays and finished for racking and forklift traffic.","scope":["Sub-base preparation and compaction","Ready-mix supply from BTB plants","Slab placement in planned pour bays","Power-float finish and saw-cut joints"],"gallery":[{"image":"/Image/bce/project_page_14.webp","caption":"Structural frame rising over prepared foundation"},{"image":"/Image/bce/project_page_15.webp","caption":"Continuous ready-mix placement and leveling"},{"image":"/Image/bce/project_page_16.webp","caption":"Concrete finishing and power-float operations"},{"image":"/Image/bce/core_services.webp","caption":"Slab placement using heavy boom pumps"}],"highlights":[{"value":"12,400","unit":"m²","label":"Slab area","note":"Single warehouse floor"},{"value":"2,600","unit":"m³","label":"Concrete placed","note":"C30 ready-mix"},{"value":"22","label":"Pour bays","note":"Day pours"},{"value":"200","unit":"mm","label":"Slab thickness","note":"Mesh reinforced"}],"equipment":[{"name":"Pump trucks","count":2},{"name":"Mixer trucks","count":8},{"name":"Power trowels","count":4},{"name":"Vibratory roller","count":1}],"technical":[{"label":"Concrete","value":"C30, slump 100 ± 25 mm"},{"label":"Finish","value":"Power-floated with dry-shake hardener"},{"label":"Joints","value":"Saw-cut at 6 m centres, sealed"}],"outcome":"The floor was ready for racking installation two weeks ahead of the tenant''s fit-out."}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
