VALUES ('projects:siem-reap-commercial-ready-mix', 'projects', 'siem-reap-commercial-ready-mix', 'published', 2, '{"slug":"siem-reap-commercial-ready-mix","sample":true,"name":"Commercial Complex Ready-Mix Supply","owner":"Private commercial developer","location":"Siem Reap City","period":"Jan 2023 – Mar 2024","category":"Ready-Mix Concrete","summary":"Continuous ready-mix supply for a four-storey commercial complex, scheduled around the contractor''s pour programme.","scope":["Mix designs for foundations, columns and slabs","Scheduled delivery from plant to site","Pumping for upper-floor slabs","Slump and cube testing on every pour"],"gallery":[{"image":"/Image/bce/hero_batching_plant.webp","caption":"Automated batching plant preparing ready-mix concrete"},{"image":"/Image/bce/project_page_17.webp","caption":"Mixer trucks staged and discharging on site"},{"image":"/Image/bce/project_page_18.webp","caption":"Upper floor structural slab concrete pouring"},{"image":"/Image/bce/laboratory_qa.webp","caption":"Slump test and compressive cube quality verification"}],"highlights":[{"value":"6,800","unit":"m³","label":"Concrete supplied","note":"Over 15 months"},{"value":"4","label":"Mix designs","note":"C25 to C35"},{"value":"1,100","label":"Truck deliveries","note":"Scheduled call-offs"},{"value":"100","unit":"%","label":"Pours tested","note":"Slump and cubes"}],"equipment":[{"name":"Mixer trucks","count":10},{"name":"Pump trucks","count":2}],"technical":[{"label":"Grades","value":"C25 slabs, C30 columns, C35 foundations"},{"label":"Quality control","value":"Slump at discharge; 6 cubes per 50 m³"}]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
