INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('projects:phnom-penh-tower-foundations', 'projects', 'phnom-penh-tower-foundations', 'published', 4, '{"slug":"phnom-penh-tower-foundations","sample":true,"name":"Mixed-Use Tower Foundations","owner":"Private developer","location":"Chamkar Mon, Phnom Penh","period":"Aug 2024 – Apr 2025","category":"Piling","summary":"Bored piles and a raft foundation for a mixed-use tower, with reinforcement, concrete and testing delivered by one team.","scope":["Bored cast-in-place piles","Reinforcement cages fabricated on site","Continuous raft foundation pour","Integrity and load testing"],"gallery":[{"image":"/Image/bce/project_page_23.webp","caption":"Heavy reinforcement steel fabrication for deep foundation"},{"image":"/Image/bce/project_page_24.webp","caption":"Structural column tying and engineering inspection"},{"image":"/Image/bce/project_page_25.webp","caption":"Continuous monolithic raft foundation concrete placement"},{"image":"/Image/bce/project_page_26.webp","caption":"Raft foundation cured and completed"}],"highlights":[{"value":"120","label":"Bored piles","note":"800 and 1,000 mm"},{"value":"32","unit":"m","label":"Pile depth","note":"Below cut-off"},{"value":"1,850","unit":"m³","label":"Raft pour","note":"Single continuous pour"},{"value":"9","unit":"mo","label":"Project period","note":"Aug 2024 – Apr 2025"}],"equipment":[{"name":"Piling rigs","count":3},{"name":"Crawler crane","count":1},{"name":"Mixer trucks","count":12},{"name":"Pump trucks","count":2}],"technical":[{"label":"Piles","value":"Bored cast-in-place, Ø 800 and 1,000 mm"},{"label":"Concrete grade","value":"C40 raft, C35 piles"},{"label":"Raft","value":"2.2 m thick, poured continuously over 26 hours"}],"outcome":"The raft was completed in a single pour with no cold joints, keeping the superstructure programme on track."}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
