INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('projects:sihanoukville-fleet-hire', 'projects', 'sihanoukville-fleet-hire', 'published', 5, '{"slug":"sihanoukville-fleet-hire","sample":true,"name":"Pump & Mixer Fleet Hire","owner":"Main contractor, hotel development","location":"Preah Sihanouk","period":"Mar 2025 – Oct 2025","category":"Truck & Equipment Rental","summary":"Concrete pump and mixer trucks hired with operators to a main contractor for structural pours on a coastal hotel.","scope":["Pump trucks with experienced operators","Mixer trucks on daily call-off","On-site maintenance and refuelling","Daily equipment reports"],"gallery":[{"image":"/Image/bce/machinery_fleet.webp","caption":"BCE fleet of 41 mixer trucks with GPS dispatch"},{"image":"/Image/bce/stats_fleet.webp","caption":"Extended boom pump trucks mobilized for high-reach pour"},{"image":"/Image/bce/hse_safety.webp","caption":"BCE certified HSE team and certified operators"}],"equipment":[{"name":"Pump trucks","count":3},{"name":"Mixer trucks","count":6}]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
