INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('vacancies:qa-materials-engineer', 'vacancies', 'qa-materials-engineer', 'published', 2, '{"id":"qa-materials-engineer","title":"Quality Assurance / Materials Testing Engineer","department":"Quality & Lab","location":"BCE In-House Laboratory, Battambang","type":"Full-Time","deadline":"31 March 2026","overview":"Perform physical testing of concrete aggregates, fresh concrete slump inspections, test cylinder casting, and DYE-2000 compressive strength evaluations in BCE''s accredited in-house testing facility.","duties":["Conduct daily quality control sampling and testing of aggregates, cement, and water per ASTM and ACI standards.","Perform on-site slump tests, temperature checks, and casting of standard 150mm concrete test cylinders.","Operate the DYE-2000 digital compressive testing machine to evaluate 7-day and 28-day breaking strength.","Maintain formal laboratory test logs, calibration certifications, and generate client quality compliance reports.","Review supplier mill test certificates for cement, reinforcement rebar, and chemical admixtures."],"qualifications":["Bachelor''s degree in Civil Engineering, Materials Science, or Quality Engineering.","Knowledge of ACI 211.1, ASTM C39, and Cambodian construction material standards.","Experience working in a construction materials testing laboratory or ready-mix QA department.","Proficiency in technical reporting, data logging, and quality compliance documentation."]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
