INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('vacancies:piling-rig-operator', 'vacancies', 'piling-rig-operator', 'published', 3, '{"id":"piling-rig-operator","title":"Hydraulic Piling Rig Operator & Field Technician","department":"Piling & Foundation","location":"Site Deployments across Cambodia","type":"Full-Time","deadline":"15 April 2026","overview":"Operate hydraulic static pile driving rigs and boring machinery on civil and industrial foundation projects across Cambodia with strict adherence to site safety blueprints.","duties":["Operate hydraulic pile driving rigs for precast reinforced concrete piles and deep foundation bored piling.","Ensure precise pile alignment, verticality inspection, and penetration resistance monitoring.","Conduct daily equipment inspection, hydraulic pressure checks, lubrication, and safety maintenance.","Coordinate with site engineers and survey teams to execute foundation layouts per engineering blueprints.","Comply with site safety protocols including full PPE and exclusion zone management during rig operation."],"qualifications":["Certified heavy machinery / hydraulic rig operator license.","3+ years experience operating hydraulic pile driving equipment or bored piling rigs in Cambodia.","Strong understanding of soil resistance, pile driving safety, and site hazard prevention.","Willingness to deploy to provincial project sites with full company accommodation and per diem."]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
