INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('vacancies:heavy-fleet-mechanic', 'vacancies', 'heavy-fleet-mechanic', 'published', 4, '{"id":"heavy-fleet-mechanic","title":"Heavy Fleet Maintenance Technician","department":"Fleet Logistics","location":"Battambang Central Workshop","type":"Full-Time","deadline":"15 April 2026","overview":"Maintain and service BCE''s fleet of 41 mixer trucks and 8 concrete boom and line pumps to ensure peak operational reliability, rapid turnaround, and zero breakdown during active pours.","duties":["Perform preventative maintenance, oil changes, brake inspections, and tire servicing across heavy truck fleet.","Diagnose and repair hydraulic motors, pump gearboxes, rotating drum systems, and pneumatic valves.","Support emergency site repairs during active concrete pours when necessary.","Maintain spare parts inventory logs, workshop safety compliance, and fleet maintenance records.","Ensure all trucks and pumping equipment meet strict road safety standards before site dispatch."],"qualifications":["Technical certificate or diploma in Heavy Vehicle Mechanics, Diesel Technology, or Hydraulic Systems.","2+ years experience servicing commercial diesel trucks (Hino, Isuzu, Howo, or similar heavy chassis).","Hands-on expertise with hydraulic pump systems, high-pressure hoses, and power take-off (PTO) units.","Hardworking, disciplined, and capable of working in shifts during major pour schedules."]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
