INSERT INTO documents (id, type, slug, status, sort, data, created_at, updated_at, updated_by)
VALUES ('vacancies:site-civil-engineer', 'vacancies', 'site-civil-engineer', 'published', 5, '{"id":"site-civil-engineer","title":"Site Civil Engineer — Ready-Mix & Foundation Works","department":"Civil Construction","location":"Site Deployments across Cambodia","type":"Full-Time","deadline":"30 April 2026","overview":"Supervise continuous concrete pour execution, foundation piling works, and structural civil projects. Ensure compliance with engineering drawings, client specifications, and HSE protocols.","duties":["Oversee on-site concrete casting, vibration, level finishing, and initial curing for structural foundations and industrial slabs.","Inspect reinforcing steel placement, formwork stability, and pile head preparation prior to concrete pour approval.","Coordinate with batching plant dispatch to maintain smooth truck delivery intervals and avoid cold joints.","Conduct daily site toolbox talks and enforce occupational safety standards across all subcontractors and field crews.","Prepare daily site progress reports, concrete volume reconciliation, and quality documentation."],"qualifications":["Bachelor''s degree in Civil Engineering, Structural Engineering, or Building Technology.","2+ years experience in structural construction, ready-mix concrete pouring, or foundation piling in Cambodia.","Proficiency in AutoCAD, construction blueprint reading, and structural bar bending schedules.","Strong leadership, problem-solving, and bilingual communication skills (Khmer / English)."]}', '2026-11-17T03:33:41.127Z', '2026-11-17T03:33:41.127Z', 'seed')
